<script setup lang="ts">
definePageMeta({layout:'workspace'})
const db=useSupabaseClient()
const {platformAdmin,load:reloadSchools}=useSchool()
type School={id:string;name:string;code:string|null;allow_student_self_registration:boolean;deactivated_at:string|null;created_at:string}
type Request={id:string;school_name:string;school_domain:string;contact_name:string;contact_email:string;contact_position:string;status:string;created_at:string;requester_id:string|null;created_school_id:string|null}
const tab=ref('schools'),schools=ref<School[]>([]),requests=ref<Request[]>([]),search=ref(''),statusFilter=ref('all'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const modalOpen=ref(false),editing=ref(false),confirmSave=ref(false)
const selectedId=ref(''),name=ref(''),code=ref(''),selfRegistration=ref(false),domains=ref<{domain:string;is_primary:boolean;is_verified:boolean}[]>([])
const selected=computed(()=>schools.value.find(s=>s.id===selectedId.value))
const filteredSchools=computed(()=>schools.value.filter(s=>(s.name+' '+(s.code||'')).toLowerCase().includes(search.value.toLowerCase())))
const filteredRequests=computed(()=>requests.value.filter(r=>statusFilter.value==='all'||r.status===statusFilter.value))
function resetEdit(){if(selected.value){name.value=selected.value.name;code.value=selected.value.code||''}editing.value=false}
function choose(s:School){selectedId.value=s.id;name.value=s.name;code.value=s.code||'';selfRegistration.value=s.allow_student_self_registration;editing.value=false;modalOpen.value=true;void loadDomains()}
async function loadDomains(){domains.value=[];if(!selectedId.value)return;const r=await db.from('school_email_domains').select('domain,is_primary,is_verified').eq('school_id',selectedId.value).order('domain');if(r.error)error.value=r.error.message;else domains.value=r.data||[]}
async function load(){if(!platformAdmin.value)return;loading.value=true;error.value='';try{const [s,r]=await Promise.all([db.from('schools').select('id,name,code,allow_student_self_registration,deactivated_at,created_at').order('name'),db.from('school_requests').select('id,school_name,school_domain,contact_name,contact_email,contact_position,status,created_at,requester_id,created_school_id').order('created_at',{ascending:false})]);if(s.error)throw s.error;if(r.error)throw r.error;schools.value=s.data||[];requests.value=r.data||[];if(selectedId.value){const updated=schools.value.find(s=>s.id===selectedId.value);if(updated){name.value=updated.name;code.value=updated.code||'';selfRegistration.value=updated.allow_student_self_registration}}}catch(e:any){error.value=e.message||'Unable to load schools'}finally{loading.value=false}}
async function save(){if(!platformAdmin.value||!selectedId.value||busy.value)return;confirmSave.value=false;busy.value=true;error.value='';notice.value='';try{const r=await db.rpc('update_school_settings',{p_school_id:selectedId.value,p_name:name.value,p_code:code.value,p_allow_student_registration:selfRegistration.value});if(r.error)throw r.error;await load();await reloadSchools();notice.value='School settings saved';editing.value=false;modalOpen.value=false}catch(e:any){error.value=e.message||'Unable to save school'}finally{busy.value=false}}
async function review(r:Request,approve:boolean){if(!platformAdmin.value||busy.value)return;if(approve&&!r.requester_id){error.value='This public enquiry has no registered requester. It requires a separate administrator invitation workflow before approval; no school has been created.';return}if(!confirm((approve?'Approve':'Reject')+' school request for '+r.school_name+'?'))return;busy.value=true;error.value='';notice.value='';try{const result=await db.rpc('review_school_request',{p_request_id:r.id,p_approve:approve,p_review_notes:null});if(result.error)throw result.error;await load();await reloadSchools();notice.value=approve?'School approved and created. Review the initial administrator membership.':'School request rejected'}catch(e:any){error.value=e.message||'Unable to review request'}finally{busy.value=false}}
watch(platformAdmin,()=>{void load()},{immediate:true})
</script>
<template><div class="space-y-6"><div><h1 class="text-2xl font-bold">Schools</h1><p class="text-sm text-[var(--muted)]">Platform administration · Registered schools and onboarding requests</p></div><UiPanel v-if="!platformAdmin">Platform Administrator access is required.</UiPanel><template v-else><div class="flex flex-wrap gap-2"><button v-for="t in [{id:'schools',label:'All Schools'},{id:'requests',label:'School Requests'}]" :key="t.id" class="rounded-xl border border-[var(--border)] px-4 py-2 text-sm font-semibold" :class="tab===t.id?'bg-blue-600 text-white':''" @click="tab=t.id">{{t.label}}<span v-if="t.id==='requests'"> ({{requests.filter(r=>r.status==='pending').length}})</span></button></div><p v-if="error" class="text-red-600" role="alert">{{error}}</p><p v-if="notice" class="text-green-600" role="status">{{notice}}</p><p v-if="loading">Loading schools…</p><UiPanel v-if="tab==='schools'"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Registered schools ({{schools.length}})</h2><input v-model="search" placeholder="Search schools" aria-label="Search schools" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></div><div v-for="s in filteredSchools" :key="s.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] py-4"><div><p class="font-semibold">{{s.name}}</p><p class="text-sm text-[var(--muted)]">{{s.code||'No code'}} · {{s.deactivated_at?'Inactive':'Active'}}</p></div><button class="rounded-lg border border-[var(--border)] px-4 py-2 text-sm" @click="choose(s)">View / Edit</button></div><p v-if="!filteredSchools.length" class="text-sm text-[var(--muted)]">No matching schools.</p></UiPanel><UiPanel v-else-if="tab==='requests'"><div class="mb-4 flex flex-wrap justify-between gap-3"><h2 class="text-lg font-bold">School registration requests</h2><select v-model="statusFilter" aria-label="Request status" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div v-for="r in filteredRequests" :key="r.id" class="border-b border-[var(--border)] py-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold">{{r.school_name}}</p><p class="text-sm text-[var(--muted)]">{{r.school_domain}} · {{r.contact_name}} ({{r.contact_position}}) · {{r.contact_email}}</p><p class="mt-1 text-sm">Status: {{r.status}} <span v-if="r.status==='pending'&&!r.requester_id">· Public enquiry – requires administrator onboarding</span></p></div><div v-if="r.status==='pending'" class="flex gap-2"><button :disabled="busy||!r.requester_id" :title="!r.requester_id?'No registered requester: manual onboarding required':''" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40" @click="review(r,true)">Approve</button><button :disabled="busy" class="rounded-lg border border-[var(--border)] px-4 py-2 text-sm" @click="review(r,false)">Reject</button></div></div></div><p v-if="!filteredRequests.length" class="text-sm text-[var(--muted)]">No requests found.</p></UiPanel></template>
<div v-if="modalOpen&&selected" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" @click.self="modalOpen=false">
<section role="dialog" aria-modal="true" aria-label="School details" class="w-full max-w-2xl rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl">
<UiHoverScrollbar max-height="calc(90vh - 48px)">
<header class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">{{editing?'Edit school':'School details'}}</h2><div class="flex items-center gap-3"><button v-if="!editing&&!selected.deactivated_at" aria-label="Edit school" title="Edit school" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="editing=true">✎</button><button aria-label="Close" @click="modalOpen=false">✕</button></div></header>
<div class="space-y-3">
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-2 text-xs text-[var(--muted)]">School name</p><input v-if="editing" v-model="name" required minlength="2" maxlength="160" aria-label="School name" class="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><strong v-else>{{selected.name}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-2 text-xs text-[var(--muted)]">School code</p><input v-if="editing" v-model="code" maxlength="30" aria-label="School code" class="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><strong v-else>{{selected.code||'Not set'}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Status</p><strong>{{selected.deactivated_at?'Inactive':'Active'}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><h3 class="mb-2 font-semibold">School email domains</h3><p class="mb-3 text-xs text-[var(--muted)]">Verification and domain changes are managed separately.</p><div v-for="d in domains" :key="d.domain" class="border-b border-[var(--border)] py-2 text-sm">{{d.domain}} · {{d.is_verified?'Verified':'Unverified'}}{{d.is_primary?' · Primary':''}}</div><p v-if="!domains.length" class="text-sm text-[var(--muted)]">No domains configured.</p></div>
</div>
<div class="mt-5 flex justify-end gap-3"><button class="rounded-xl border border-[var(--border)] px-5 py-3" @click="editing?resetEdit():modalOpen=false">{{editing?'Cancel':'Close'}}</button><button v-if="editing" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white" :disabled="busy||name.trim().length<2" @click="confirmSave=true">Save changes</button></div>
</UiHoverScrollbar></section></div>
<div v-if="confirmSave" class="fixed inset-0 z-[60] grid place-items-center bg-black/70 p-4"><section role="alertdialog" aria-modal="true" class="w-full max-w-sm rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><h3 class="text-lg font-bold">Save school changes?</h3><p class="mt-3 text-sm">Update the school name and code?</p><div class="mt-6 flex justify-end gap-3"><button class="rounded-xl border border-[var(--border)] px-4 py-2" @click="confirmSave=false">Cancel</button><button class="rounded-xl bg-blue-600 px-4 py-2 text-white" :disabled="busy" @click="save">Yes, save</button></div></section></div>
</div></template>